import{c as e,Q as r,j as o,m as a}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Recovery Execution Status & Output Results","description":"Understand the recovery execution outcomes: completed, partial, waiting_to_rerun, or failed. Learn how to verify transactions on Arbitrum and Hyperliquid L1.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/execution-status"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/execution-status"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/execution-status"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/execution-status"}],["meta",{"name":"keywords","content":"Hyperliquid execution status, recovery status partial, transaction hash verification, failed recovery troubleshooting"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Recovery Execution Status & Output Results"}],["meta",{"property":"og:description","content":"Understand the recovery execution outcomes: completed, partial, waiting_to_rerun, or failed. Learn how to verify transactions on Arbitrum and Hyperliquid L1."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/execution-status"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Recovery Execution Status & Output Results"}],["meta",{"name":"twitter:description","content":"Understand the recovery execution outcomes: completed, partial, waiting_to_rerun, or failed. Learn how to verify transactions on Arbitrum and Hyperliquid L1."}]]},"headers":[],"relativePath":"en/execution-status.md","filePath":"en/execution-status.md","lastUpdated":null}'),i={name:"en/execution-status.md"};function d(n,t,s,l,u,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="execution-status" tabindex="-1">Execution Status <a class="header-anchor" href="#execution-status" aria-label="Permalink to &quot;Execution Status&quot;">​</a></h1><p>The recovery system uses two layers of status: step-level statuses describe each operation, while task-level outcomes explain how to understand the entire recovery run and what to do next.</p><h2 id="task-level-outcomes" tabindex="-1">Task-Level Outcomes <a class="header-anchor" href="#task-level-outcomes" aria-label="Permalink to &quot;Task-Level Outcomes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outcome</th><th>Meaning</th><th>Recommended Action</th></tr></thead><tbody><tr><td>completed</td><td>This run produced actual progress or recovered funds, and no immediate rerun is needed</td><td>No immediate rerun needed</td></tr><tr><td>partial</td><td>This run only partially progressed, or recovered nothing while assets still remain blocked/waiting</td><td>Review the summary and follow up as needed</td></tr><tr><td>waiting_to_rerun</td><td>This run progressed successfully, but protocol waiting or lock windows remain</td><td>Rerun after the waiting window ends</td></tr><tr><td>failed</td><td>This run was interrupted by a fatal error</td><td>Fix the root cause before retrying</td></tr></tbody></table><h2 id="step-level-statuses" tabindex="-1">Step-Level Statuses <a class="header-anchor" href="#step-level-statuses" aria-label="Permalink to &quot;Step-Level Statuses&quot;">​</a></h2><h2 id="status-matrix" tabindex="-1">Status Matrix <a class="header-anchor" href="#status-matrix" aria-label="Permalink to &quot;Status Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Icon</th><th>Meaning</th><th>Recommended Action</th></tr></thead><tbody><tr><td>completed</td><td>✅</td><td>Step fully completed</td><td>Wait for next steps</td></tr><tr><td>completed_partial</td><td>⚠️</td><td>Partial success, some assets skipped or failed</td><td>Review notes and rerun if needed</td></tr><tr><td>completed_waiting</td><td>⏰</td><td>Operation succeeded but protocol waiting period applies</td><td>Rerun at suggested time</td></tr><tr><td>skipped_locked</td><td>🔒</td><td>Assets currently locked</td><td>Wait for unlock and rerun</td></tr><tr><td>skipped_no_assets</td><td>➖</td><td>No eligible assets for this step</td><td>No action required</td></tr><tr><td>failed_system_error</td><td>❌</td><td>System-level failure</td><td>Retry later or contact support</td></tr><tr><td>failed_user_error</td><td>⛔</td><td>Input or configuration issue</td><td>Fix input and retry</td></tr><tr><td>failed_network_error</td><td>🌐❌</td><td>Network or RPC issue</td><td>Check network and retry</td></tr></tbody></table><h2 id="typical-interpretations" tabindex="-1">Typical Interpretations <a class="header-anchor" href="#typical-interpretations" aria-label="Permalink to &quot;Typical Interpretations&quot;">​</a></h2><ul><li><code>⚠️ completed_partial</code>: common when only part of vault/staking assets are currently executable.</li><li><code>⏰ completed_waiting</code>: common in staking, where execution succeeds but unlock windows remain (for example, 1-day or 7-day waiting periods).</li><li><code>🔒 skipped_locked</code>: not a hard failure; it indicates protocol lock state.</li><li>If the whole run is only <code>skipped_*</code> and no funds are actually recovered, the task-level outcome becomes <code>partial</code>, not <code>completed</code>.</li></ul><h2 id="when-to-rerun-recovery" tabindex="-1">When to Rerun Recovery <a class="header-anchor" href="#when-to-rerun-recovery" aria-label="Permalink to &quot;When to Rerun Recovery&quot;">​</a></h2><ul><li>If the task-level outcome is <code>waiting_to_rerun</code>, rerun after the suggested unlock time.</li><li>If the task-level outcome is <code>completed</code>, no immediate extra action is usually required.</li><li>If the task-level outcome is <code>partial</code>, review the remaining issues before deciding whether to rerun now.</li><li>If step outputs include <code>failed_*</code> and the task-level outcome is <code>failed</code>, resolve the root cause first, then rerun.</li></ul>',11)])])}const m=e(i,[["render",d]]);export{p as __pageData,m as default};
